from fractions import Fraction as F
opts = {"A": F(25, 36), "B": F(36, 25), "C": F(25, 32), "D": F(32, 25)}
target = {2019: 40, 2020: 44, 2021: 70, 2022: 80}
actual = {2019: 36, 2020: 32, 2021: 59, 2022: 65}
result = F(target[2021] + target[2022], sum(actual.values()))

match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")
